# owner: platform
"""Absence notices that can be sent home to parents."""

from typing import List
from rosterkit.models import Student
from rosterkit.attendance import days_missed
from datetime import date

# ---
def absence_notice(student: Student, marks: list) -> str:
    owners = {mark.student_id for mark in marks}
    if owners - {student.student_id}:
        raise ValueError("marks belong to another student")
    missed = days_missed(marks)
    if not missed:
        raise ValueError("no absences to report")
    return _notice(student, missed)

def _notice(student: Student, missed: List[date]) -> str:
    word = "day" if len(missed) == 1 else "days"
    listed = ", ".join(when.isoformat() for when in missed)
    return (
        f"{student.display_name} was absent "
        f"{len(missed)} {word}: {listed}."
    )
